pub const fn ahri_e(ctx: &Ctx) -> f32 {
    40f32 * (1f32 + 0.021249999999999998 * ctx.ability_power + ctx.e_level)
}

pub const fn ahri_rmin(ctx: &Ctx) -> f32 {
    25f32 * (2f32 + 0.013999999999999999 * ctx.ability_power + ctx.r_level)
}

pub const fn ahri_rmax(ctx: &Ctx) -> f32 {
    75f32 * (2f32 + 0.013999999999999999 * ctx.ability_power + ctx.r_level)
}

