pub const fn braum_p(ctx: &Ctx) -> f32 {
    2f32 * (13f32 + 5f32 * (-1f32 + ctx.level))
}

pub const fn braum_p1(ctx: &Ctx) -> f32 {
    0.8 * (5.2 + 0.2 * ctx.steelcaps_effect + 2f32 * (-1f32 + ctx.level))
}

pub const fn braum_q(ctx: &Ctx) -> f32 {
    15f32
        * (5f32
            + 0.0016666666666666668 * ctx.max_health
            + 3f32 * (-1f32 + ctx.q_level))
}

pub const fn braum_r(ctx: &Ctx) -> f32 {
    50f32 * (2f32 + 0.012 * ctx.ability_power + ctx.r_level)
}

